exp as (select m.latin, p.label, p.lat, p.lng, p.r, ord.n, p.i from map m cross join lateral unnest(string_to_array(m.keys, ',')) with ordinality ord(k, n) join pre p on p.k = ord.k),
agg as (select latin, jsonb_agg(jsonb_build_object('label', label, 'lat', lat, 'lng', lng, 'r', r) order by n, i) areas from exp group by latin)
update public.species s set range_areas = a.areas from agg a where a.latin = s.latin or (a.latin = '__malawi' and s.category_id = 'malawi') or (a.latin = '__tanganyika' and s.category_id = 'tanganyika' and s.latin <> 'Synodontis multipunctatus');
